def can_distribute_candies(a, b, c):
    candies = [a, b, c]
    total_candies = sum(candies)

    if total_candies % 2 != 0:
        return "No"

    target = total_candies // 2

    if target in candies:
        return "Yes"

    candies.sort()

    for i in range(3):
        for j in range(i + 1, 3):
            if candies[i] + candies[j] == target:
                return "Yes"

    for i in range(3):
        remainder = target - candies[i]
        if remainder > 0:
            complement_pairs = [
                (candies[(i + 1) % 3], candies[(i + 2) % 3]),
                (candies[(i + 2) % 3], candies[(i + 1) % 3])
            ]
            for pair in complement_pairs:
                if pair[0] + pair[1] == remainder:
                    return "Yes"

    return "No"

